// Generated from the individually edited RU event-outcomes catalog (E361-E430).
// Literary strings only. Gameplay mechanics stay in events-core.mjs.
const OUTCOMES_E361_E430 = Object.freeze({"E361.1":{"s":"Верн соглашается дать Г-17 заслуженный выходной, а строители впервые обсуждают отдых и для себя. Они выплачивают отряду золото за посредничество.","f":"Верн отказывается менять расписание из-за надписи мелом. Г-17 остаётся неподвижен, и стройка не продвигается."},"E361.2":{"s":"Вы делитесь припасами с рабочими, вынужденными ждать подъёма блока. Верн платит золотом за помощь в день незапланированного простоя."},"E361.3":{"s":"{{heroName}} проверяет шарниры Г-17 и подтверждает, что поломки нет: голем сам прекратил работу. Верн платит золотом за ясный ответ.","f":"При проверке массивный блок соскальзывает с опоры и тяжело ранит {{affectedHeroName}}. Причину остановки голема так и не выяснили.","v":{"nf":"Блок срывается с опоры, но никто из допустимых бойцов не получает тяжёлого ранения. Г-17 по-прежнему отказывается работать."}},"E361.4":{"s":"Вы оставляете Г-17 и Верна обсуждать двадцать три года работы без выходных. Строители уже примеряют это право к собственному расписанию."},"E362.1":{"s":"Вы заставляете К-4 выдать монеты за неподходящий товар. Нара благодарит золотом за остановленную торговлю ложками.","f":"К-4 вновь открывает ящик и выдаёт ложку вместо возврата. Очередь покупателей становится только длиннее."},"E362.2":{"s":"Вы покупаете припасы прямо у Нары, минуя упрямый автомат. К-4 тем временем предлагает деревянную ложку очередному заказчику."},"E362.3":{"s":"{{heroName}} обнаруживает в управляющей схеме зацикленную команду выдачи ложек. Нара выплачивает золото за найденную причину.","f":"Медный механизм внезапно сжимает рабочую руку, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Автомат захлопывает сервисный отсек, но никто из допустимых бойцов не получает тяжёлого ранения. Ложки продолжают выпадать."}},"E362.4":{"s":"Вы не рискуете покупать хлеб у машины с единственным ответом. На площади уже спорят, сколько ложек считается одним мешком муки."},"E363.1":{"s":"Вы преодолеваете заграждение, не дожидаясь разрешения М-8, и проходите за ворота. Смена караула смотрит на вас с завистью.","f":"Страж объявляет попытку прохода нарушением приказа и поднимает боевых конструктов. Начинается битва."},"E363.2":{"s":"Вы покупаете у караванщиков припасы и устраиваетесь ждать, пока Сена разбирается с бронзовым стражем. Из-за ворот доносится пароль, который вновь признают правильным."},"E363.3":{"s":"{{heroName}} обнаруживает два взаимоисключающих приказа: пароль верен, но старый запрет не отменён. Сена исправляет распоряжение и благодарит золотом.","f":"{{heroName}} находит печати обоих приказов подлинными, но ни один не имеет старшинства. М-8 по-прежнему запрещает проход."},"E363.4":{"s":"Вы тратите припасы на обход ворот и оставляете Сену объясняться со стражем. М-8 ещё раз подтверждает, что пароль верен."},"E364.1":{"s":"Вы остаётесь на площади и замечаете, как пропущенная минута оставляет у часов золотую вещь неизвестного владельца. Находка пополняет казну.","f":"Ровно перед полуднем на площади появляются вооружённые чужаки, словно выпавшие из исчезнувшей минуты. Начинается стычка."},"E364.2":{"s":"Вы покупаете у Ира припасы и уходите до двенадцати. Часовщик обещает на этот раз не моргать, когда стрелки перескочат."},"E364.3":{"s":"{{heroName}} распознаёт короткий разрыв в рунном циферблате и находит спрятанное под ним золото. Ир благодарит за разгадку.","f":"Когда стрелки пропускают минуту, {{affectedHeroName}} получает тяжёлое ранение от внезапного удара часового механизма.","v":{"nf":"Часы обрывают наблюдение опасным скачком, но никто из допустимых бойцов не получает тяжёлого ранения. Исчезнувшая минута остаётся тайной."}},"E364.4":{"s":"Вы оставляете Ира следить за минутой, которую его часы отказываются показывать. На площади уже готовят место для завтрашнего следа."},"E365.1":{"s":"Дун садится напротив Л-3 и слышит знакомую историю о матери, не решаясь перебить. За возможность поговорить мастер Кира передаёт отряду золото.","f":"Дун не выдерживает, когда конструкт произносит ласковое имя его детства, и прекращает разговор. Объяснения не находится."},"E365.2":{"s":"Вы оставляете Кире припасы для новых проверок памяти. Мастер благодарит золотом, а Л-3 продолжает рассказывать чужое детство."},"E365.3":{"s":"{{heroName}} обнаруживает в памяти конструкта след старой записи, совпадающей с рассказом Дуна. Кира благодарит золотом за зацепку.","f":"Скрытая печать памяти отбрасывает исследователя, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Печать памяти прерывает исследование, но никто из допустимых бойцов не получает тяжёлого ранения. Дун и Л-3 остаются без ответа."}},"E365.4":{"s":"Вы не решаете за Дуна и Л-3, кому принадлежит одно воспоминание о Селле. Они продолжают говорить о доме, которого давно нет."},"E366.1":{"s":"Вы признаёте право Р-1 самому решать, продолжать ли службу. Теса платит золотом за честное посредничество, хотя разборку пока не начинает.","f":"Теса отказывается признать просьбу машины окончательным решением. Р-1 остаётся ждать разговора, а не инструментов."},"E366.2":{"s":"Р-1 соглашается сначала прекратить работу и пожить без заданий. Ученики дают отряду припасы за возможность обдумать выбор без спешки.","f":"Р-1 считает паузу ещё одним навязанным заданием и отказывается от вашего предложения. Спор остаётся открытым."},"E366.3":{"s":"{{heroName}} проверяет память и механизмы Р-1, не находя ошибки, которая объясняла бы просьбу. Теса платит золотом за проверку.","f":"При вскрытии рабочего отсека срабатывает защита, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Защита корпуса срывает осмотр, но никто из допустимых бойцов не получает тяжёлого ранения. Причину просьбы подтвердить не удаётся."}},"E366.4":{"s":"Вы не принимаете решение вместо разумной машины и уходите. Р-1 остаётся с Тесой, чтобы они могли договорить без посторонних."},"E367.1":{"s":"Вы предлагаете ворону отполированную пуговицу, и тот отдаёт за неё несколько украденных монет. Золото пополняет казну.","f":"Птица смотрит на ваш блестящий хлам, затем решительно отворачивается к чужому шлему. Сделка не состоялась."},"E367.2":{"s":"Вы возвращаете Эмме часть украденных птицей монет, а торговка делится дорожной едой. Ворон уже оценивает её новую застёжку.","f":"Эмма не может доказать, какая именно монета пропала с её телеги, и отказывается от обмена. Припасов отряд не получает."},"E367.3":{"s":"{{heroName}} обменивает ненужную железную пряжку на вороний запас золота, сохранив ценные вещи отряда.","f":"Ворон хватает настоящий золотой застёжку с пояса и уносит её прежде, чем {{heroName}} успевает вмешаться. Казна теряет золото."},"E367.4":{"s":"Вы оставляете ворона управлять рынком блестящих вещей. Эмма пересчитывает монеты, пока один возчик полирует ложку рукавом."},"E368.1":{"s":"Вы дожидаетесь, пока по реке проплывает забытая лодка с золотом, и олень наконец отступает с моста. Находка достаётся отряду.","f":"Под мостом появляются вооружённые чужаки, пришедшие по течению вслед за неизвестным предметом. Начинается стычка."},"E368.2":{"s":"Вы расходуете припасы на переправу вброд, не тревожа оленя. Он всё так же смотрит вниз на реку."},"E368.3":{"s":"{{heroName}} исследует течение и находит у старых свай золото с уцелевшими припасами. Олень впервые поворачивает голову к берегу.","f":"На размытой кромке берега {{affectedHeroName}} получает тяжёлое ранение, когда под ногами обваливается грунт.","v":{"nf":"Берег осыпается под разведкой, но никто из допустимых бойцов не получает тяжёлого ранения. Причину ожидания оленя не удаётся выяснить."}},"E368.4":{"s":"Вы не мешаете оленю ждать на узком мосту. Он делает ещё один шаг назад, когда под ним проплывает бревно."},"E369.1":{"s":"Вы отвлекаете медведя и возвращаете монахам колокол без новых трещин. Звонарь Пир благодарит золотом за спасённую святыню.","f":"Медведь сжимает колокол в лапах и неожиданно налетает на {{affectedHeroName}}, причиняя тяжёлое ранение.","v":{"nf":"Медведь отбивает попытку отнять игрушку, но никто из допустимых бойцов не получает тяжёлого ранения. Колокол остаётся в лесу."}},"E369.2":{"s":"Вы оставляете монахам припасы для продолжения погони. Пир благодарит золотом, пока колокол снова звенит далеко среди деревьев."},"E369.3":{"s":"{{heroName}} выводит медведя на открытый склон, где монахи успевают обменять колокол на большой металлический котёл. Пир платит золотом.","f":"В узком проходе медведь резко бросается в сторону, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Медведь срывает загон, но никто из допустимых бойцов не получает тяжёлого ранения. Звон продолжает удаляться."}},"E369.4":{"s":"Вы оставляете монахов преследовать звон, который и так слышен за две мили. Лес отвечает на каждый медвежий шаг новым ударом колокола."},"E370.1":{"s":"Вы помогаете Лему вывести гусей с плаца на дальний луг, и солдаты возвращаются к строевой. В благодарность они выдают припасы.","f":"Гуси отказываются покидать сержанта и строятся за ним ещё плотнее. Отвести их от лагеря не получается."},"E370.2":{"s":"Вы покупаете у солдат припасы, пока Лем пытается забрать у гуся свисток. Птица отвечает особенно громким шипением."},"E370.3":{"s":"{{heroName}} выясняет, что гуси слушаются не команд, а свистка, который украл вожак. Лем благодарит золотом за разгадку.","f":"{{heroName}} пробует все строевые команды, но гуси исполняют лишь те, что им нравятся. Сержант остаётся без решения."},"E370.4":{"s":"Вы оставляете Лема командовать стаей, которая назначила его сама. Один гусь важно шагает впереди с украденным свистком."},"E371.1":{"s":"Вы отводите старого льва в сторону, не поднимая на него оружия. Родные наконец могут проводить охотника и благодарят золотом.","f":"Лев принимает приближение за угрозу покойному и выходит навстречу с обнажёнными когтями. Начинается стычка."},"E371.2":{"s":"Вы оставляете семье припасы для долгого ожидания. Мать охотника благодарит золотом, пока лев продолжает лежать у могилы."},"E371.3":{"s":"{{heroName}} предлагает провести прощание там, где лежит лев, не прогоняя его от тела. Семья платит золотом за возможность похоронить своего.","f":"Лев рывком встаёт на пути погребального обряда, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Зверь останавливает обряд, но никто из допустимых бойцов не получает тяжёлого ранения. Похороны приходится отложить."}},"E371.4":{"s":"Вы не мешаете старому льву прощаться с охотником. Мать жестом останавливает сына, когда тот снова тянется к оружию."},"E372.1":{"s":"Вы идёте по следу хозяина и находите у старого брода оставленный золотой кошель. Собаки продолжают караулить пустую повозку.","f":"След приводит в засаду вооружённых людей, знавших о пропавшем вознице. Начинается битва."},"E372.2":{"s":"Вы оставляете собакам часть провизии возле пустых мисок. Ни одна из шести не отходит от повозки, пока еда не съедена."},"E372.3":{"s":"{{heroName}} проходит первые мили по следу и находит в укрытии золотую кассу пропавшего возницы. Отряд забирает её, не трогая собак.","f":"На тропе преследования {{affectedHeroName}} получает тяжёлое ранение от скрытой ловушки.","v":{"nf":"След ведёт в опасное место, но никто из допустимых бойцов не получает тяжёлого ранения. Найти хозяина не удаётся."}},"E372.4":{"s":"Вы оставляете повозку и шесть верных сторожей на дороге. Перчатка хозяина остаётся лежать на сложенном одеяле."},"E373.1":{"s":"Вы объясняете Ниме, что вчерашний день прошёл не из-за ремонта часов. Часовщик благодарит золотом за прекращённую претензию.","f":"Нима требует квитанцию на возвращение вчера и не признаёт слова о календаре. Часовщик снова заводит часы."},"E373.2":{"s":"Вы покупаете у часовщика припасы и уходите, пока Нима заполняет воображаемую жалобную книгу времени."},"E373.3":{"s":"{{heroName}} показывает фее, что оплачена была починка часов, а не остановка календаря. Часовщик платит золотом за ясное решение.","f":"{{heroName}} не находит формулировки, которую Нима готова принять: она по-прежнему требует недожитый день. Спор продолжается."},"E373.4":{"s":"Вы не обещаете Ниме вернуть вчера и продолжаете путь. За спиной слышно, как фея требует жалобную книгу на завтра."},"E374.1":{"s":"Клем соглашается оставить старый сапог муравьям вместе с пряжкой. Аниса благодарит отряд припасами за сохранённый храм.","f":"Клем не желает отдавать серебряную пряжку муравьиному жречеству и тянется к сапогу. Договориться не удаётся."},"E374.2":{"s":"Вы платите Клему за право на пряжку, но не трогаете миниатюрный храм. Муравьи продолжают охранять своё святилище."},"E374.3":{"s":"{{heroName}} узнаёт в муравьиных ритуалах обычай освящать найденное убежище. Аниса благодарит золотом за объяснение.","f":"{{heroName}} не может разобраться в движениях крошечных жрецов. Муравьи продолжают защищать пряжку."},"E374.4":{"s":"Вы оставляете новую святыню её маленьким прихожанам. Клем задумчиво оценивает, сколько его старой обуви ещё годится для храмов."},"E375.1":{"s":"Вы отворачиваетесь от бабочки и делаете вид, что выбрали другой путь, пока она ведёт отряд к съестному тайнику. Припасы пополняются.","f":"Бабочка замечает слишком явное преследование и возвращается на исходный камень. На поиски обхода уходят припасы."},"E375.2":{"s":"Вы платите Элу за обычный маршрут, который не требует обманывать бабочку. Проводник с заметным облегчением берётся за карту."},"E375.3":{"s":"{{heroName}} выбирает тропу в стороне, а бабочка добровольно показывает короткий проход к запасам еды. Отряд получает припасы.","f":"На отвлекающем маршруте {{affectedHeroName}} получает тяжёлое ранение от скрытого препятствия.","v":{"nf":"Ложный маршрут заводит в опасный проход, но никто из допустимых бойцов не получает тяжёлого ранения. Бабочка возвращается на камень."}},"E375.4":{"s":"Вы выбираете дорогу без хитрости и оставляете Эла спорить с поведением бабочки. Она сидит на камне, будто всё понимает."},"E376.1":{"s":"Вы осторожно пересаживаете сорванный цветок обратно в заповедную рощу. Страж-божья коровка освобождает караван, а Рам благодарит припасами.","f":"Цветок не приживается на прежнем месте, и божья коровка не снимает задержание. Караван остаётся у рощи."},"E376.2":{"s":"Вы делитесь провизией с возчиками, застрявшими на дороге. Купец Рам благодарит золотом за помощь во время задержания."},"E376.3":{"s":"{{heroName}} через переводчицу предлагает пересадить цветок и охранять его до укоренения. Божья коровка соглашается, а Рам выдаёт золото.","f":"{{heroName}} не может убедить стража, что денежный штраф заменит возвращение цветка. Дорога остаётся перекрытой."},"E376.4":{"s":"Вы обходите задержанный караван и не вступаете в спор о сорванном цветке. Фея-переводчица продолжает терпеливо шевелить усиками вместо стража."},"E377.1":{"s":"Пик соглашается покинуть шлем до турнира, когда Дорн обещает ей новое жильё. Рыцарь благодарит золотом за освобождённую защиту.","f":"Фея показывает договор аренды до первой грозы и не намерена переезжать при ясном небе. Дорн остаётся без шлема."},"E377.2":{"s":"Вы оплачиваете Пик переселение, и фея выносит из шлема крошечную кровать с занавеской. Дорн проверяет, не забыла ли она носки."},"E377.3":{"s":"{{heroName}} приспосабливает для Пик пустую лампу с безопасной вентиляцией, и фея добровольно освобождает шлем. Дорн благодарит золотом.","f":"{{heroName}} не находит жилища, которое Пик сочла бы столь же удобным, как рыцарский шлем. Переезд откладывается."},"E377.4":{"s":"Вы желаете Дорну хорошей погоды перед турниром. Фея уверяет, что первая гроза всё равно когда-нибудь придёт."},"E378.1":{"s":"Вы успеваете до последнего удара колокола купить припасы и вынести их с исчезающего рынка.","f":"Рынок исчезает, когда продавец ещё считает сдачу, а комиссия за неоконченную сделку остаётся с вас. Казна теряет дополнительное золото."},"E378.2":{"s":"Вы перепродаёте спешащим покупателям готовые свёртки и получаете золото ещё до конца минуты.","f":"Покупатели проносятся мимо ваших предложений, а рынок исчезает прежде, чем кто-либо совершает сделку."},"E378.3":{"s":"{{heroName}} заранее отмечает нужные лавки, и отряд добирается до них за несколько мгновений. Припасы куплены до исчезновения рынка.","f":"{{heroName}} ошибается с очередностью палаток, и часть припасов теряется в толчее последней секунды."},"E378.4":{"s":"Вы наблюдаете, как за одну минуту целая площадь исчезает вместе с рынком. Человек со списком на рукаве всё ещё смотрит на свои пустые руки."},"E379.1":{"s":"Вы покупаете у Жика карту и находите под половицей настоящий золотой тайник. Мопа немедленно требует посмотреть, что ещё муж отметил как секретное.","f":"Тайник под половицей оказывается пустым, хотя карта вполне точна. Уплаченные за план монеты не возвращаются."},"E379.2":{"s":"Вы покупаете у Мопы припасы вместо карты семейного дома. Она просит не рассказывать Жику, что кладовая тоже имеет цену."},"E379.3":{"s":"{{heroName}} находит на плане полезную отметку тайника, не предназначенную для посторонних. Жик выдаёт золото, чтобы избежать семейного скандала.","f":"{{heroName}} обнаруживает только переименованные домашние комнаты. Никакого безопасного убежища на карте нет."},"E379.4":{"s":"Вы оставляете Жика и Мопу спорить о тайнике под половицей. Карта собственного дома внезапно становится семейной уликой."},"E380.1":{"s":"Вы показываете фермерам деревянную лапу и заставляете Грикса вернуть страховые взносы. Отряд получает золото за разоблачение.","f":"Грикс называет деревянную лапу доказательством особо хитрого дракона и зовёт вооружённых помощников. Начинается стычка."},"E380.2":{"s":"Вы покупаете у фермеров припасы, пока они выясняют у страховщика назначение деревянной лапы."},"E380.3":{"s":"{{heroName}} находит в договоре условие о реальном следе дракона и предъявляет деревянную подделку. Грикс возвращает золото.","f":"{{heroName}} не может доказать, что Грикс сам подделал след, и страховщик взыскивает плату за юридический разбор. Казна теряет золото."},"E380.4":{"s":"Вы отказываетесь покупать страховку от дракона, которого никто не видел. Грикс уже убеждает фермеров, что деревянные лапы бывают и у настоящих чудовищ."},"E381.1":{"s":"Бульк наливает вам из общего котла «королевский ужин»; походные миски пополняются припасами. Разницу с «супом путешественника» найти не удаётся."},"E381.2":{"s":"Вы выставляете четыре одинаковые тарелки перед Бульком, и он нехотя возвращает золотую разницу за выдуманное разнообразие.","f":"Повар объявляет различие исключительно эмоциональным, и никто не может доказать обратное. Скидки нет."},"E381.3":{"s":"{{heroName}} обнаруживает за кухней большой запас продуктов, который Бульк так и не использовал. За молчание о складе повар выдаёт припасы.","f":"{{heroName}} задевает незакреплённую полку, и часть припасов отряда портится вместе с содержимым кухни."},"E381.4":{"s":"Вы уходите из ресторана с двадцатью тремя названиями одной похлёбки. Бульк уже дописывает в меню двадцать четвёртое."},"E382.1":{"s":"Инспектор видит, как крыса уверенно обходит яму, и разрешает Пуку продолжить путь. Возчик платит золотом за спасённую поездку.","f":"Инспектор требует подпись водителя, а крыса оставляет на бумаге след зубов. Разрешения всё ещё нет."},"E382.2":{"s":"Вы покупаете у Пука припасы прямо из кузова. Крыса терпеливо придерживает поводья, пока он ищет мешки."},"E382.3":{"s":"{{heroName}} проверяет упряжь и замечает, что крыса реагирует на повороты раньше хозяина. Инспектор благодарит золотом за испытание.","f":"{{heroName}} не может убедить инспектора признать вождение без подписи. Телега остаётся у обочины."},"E382.4":{"s":"Вы не участвуете в выдаче прав крысам. Пук снова засыпает, а его маленький возница терпеливо ждёт разрешения."},"E383.1":{"s":"Вы возвращаете Зибу счёты, и банкир немедленно проверяет остаток по всем счетам. За спасённые операции он платит золотом.","f":"Мальчик не хочет расставаться с бусинами, а Зиб отказывается считать без них. Переговоры заходят в тупик."},"E383.2":{"s":"Зиб соглашается выплатить крупную награду и с облегчением получает свои счёты. Золото переходит в казну.","f":"Банкир объявляет предложенную сумму невозможной, а за обсуждение взыскивает золото по банковскому тарифу."},"E383.3":{"s":"{{heroName}} проверяет расчёты Зиба до возврата счётов и обнаруживает ошибку в старой ведомости. За исправление банкир платит золотом.","f":"{{heroName}} не успевает сверить все счёты без бусин. Зиб требует сначала вернуть инструмент."},"E383.4":{"s":"Вы оставляете гоблинский банк без счётов. За спиной мальчик с удовольствием передвигает бусины будущего финансового кризиса."},"E384.1":{"s":"Вы меняете угол ковша, и посылка опускается прямо к ожидающему получателю. Флюк платит золотом за первую доставку без синяков.","f":"Катапульта дёргается при пуске, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Пуск оказывается опасным, но никто из подходящих бойцов не получает тяжёлого ранения. Посылку отправлять не решаются."}},"E384.2":{"s":"Вы покупаете припасы у помощников Флюка, пока на другом берегу требуют запретить отправку сковородок."},"E384.3":{"s":"{{heroName}} измеряет ветер и уменьшает дальность броска; коробка приземляется точно в отмеченный круг. Флюк платит золотом.","f":"Рычаг неожиданно отпускает ковш, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Ковш срабатывает преждевременно, но никто из подходящих бойцов не получает тяжёлого ранения. Испытание отменяют."}},"E384.4":{"s":"Вы отказываетесь отправлять что-либо по воздуху и продолжаете путь. Флюк уже записывает претензию о сковороде как удачную доставку."},"E385.1":{"s":"Вы возвращаете указатель к старой мельнице и объявляете путь доступным всем. Ангел и демон выплачивают золото за окончание спора.","f":"Эриэль и Хасс снова поворачивают табличку каждый в свою сторону. Нейтральное положение не удержалось."},"E385.2":{"s":"Вы платите за сведения о безопасном пути и уходите, оставив Эриэля с Хассом бороться за стрелку."},"E385.3":{"s":"{{heroName}} предлагает вписать храм и ярмарку на разные стороны указателя. За завершённое разбирательство вам выдают золото.","f":"Демон считает решение предательством, и его помощники закрывают перекрёсток. Начинается стычка."},"E385.4":{"s":"Вы выбираете дорогу самостоятельно, не требуя подписи небес или преисподней. Старое слово «мельница» исчезает за поворотом."},"E386.1":{"s":"Вы поддерживаете леса Брака, пока тот соединяет два конца сияния без железных заклёпок. Дварф благодарит золотом.","f":"Леса сдвигаются под мастерами, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Леса падают, но никто из подходящих бойцов не получает тяжёлого ранения. Радуга остаётся разорванной."}},"E386.2":{"s":"Вы отдаёте Луми припасы для магического обряда, и она возвращает цветам прежний порядок. Фея благодарит золотом."},"E386.3":{"s":"{{heroName}} находит способ закрепить опоры вне светящейся дуги. Брак выплачивает золото за сохранённую радугу.","f":"Металлическая скоба внезапно вырывается из опоры и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Скоба срывает работу, но никто из подходящих бойцов не получает тяжёлого ранения. Разрыв остаётся прежним."}},"E386.4":{"s":"Вы оставляете Брака мерить радугу линейкой, а Луми — возмущаться словом «скоба». Цвета всё ещё не сходятся."},"E387.1":{"s":"Вы просите молодых эльфов вытереть сапоги перед входом и признаёте труд Драга. Элви благодарит припасами за спокойствие сада.","f":"Ученики отказываются принимать приказ бывшего врага и продолжают стоять перед воротами. Спор не разрешён."},"E387.2":{"s":"Элви продаёт вам припасы из садового склада. Драг придирчиво проверяет грязь на сапогах каждого носильщика."},"E387.3":{"s":"{{heroName}} убеждает юношей сначала посмотреть, как Драг ухаживает за деревьями. Элви благодарит золотом за мирный проход.","f":"Один из учеников объявляет беседу оскорблением павших и зовёт друзей на стычку."},"E387.4":{"s":"Вы вытираете ноги и входите в сад, не возражая Драгу. Орк одобрительно кивает, а молодые эльфы отворачиваются."},"E388.1":{"s":"Вы считаете скелетов по черепам, и Селий принимает число двадцать семь без дробей. Вессар платит золотом за закрытую ведомость.","f":"Скелет без нижней части тела требует двойного учёта за самостоятельность. Спор возвращается к началу."},"E388.2":{"s":"Вы покупаете у Вессара припасы, пока ангел продолжает вести расчёты. Один скелет перекладывает ногу в другую руку."},"E388.3":{"s":"{{heroName}} вводит правило: каждая самостоятельная нежить учитывается один раз, независимо от набора костей. Некромант благодарит золотом.","f":"Селий требует дополнительной графы для отсутствующих конечностей, и ведомость снова расходится."},"E388.4":{"s":"Вы оставляете ангела считать половину скелета. Тот молча поднимает отдельную ногу в знак несогласия."},"E389.1":{"s":"Вы доказываете, что один гоблин тоже относится к категории «гоблины», и Клеп выплачивает страховку. Дракон выдаёт золото за посредничество.","f":"Клеп зовёт вооружённых помощников и требует защищать договор от драконьего давления. Начинается стычка."},"E389.2":{"s":"Вы оплачиваете часть пропажи за Клепа и прекращаете спор прежде, чем воздух станет огнём. Иаракс нехотя остывает."},"E389.3":{"s":"{{heroName}} показывает, что страховой случай определяется кражей, а не числом воров. Клеп выдаёт золото за признанную ошибку.","f":"{{heroName}} обнаруживает платное толкование спорного пункта, и казна теряет золото. Иаракс продолжает нагреваться."},"E389.4":{"s":"Вы отходите от застрахованного пожара, пока Клеп спорит о числе гоблинов. Переводчик отступает вслед за вами."},"E390.1":{"s":"Вы идёте по ровным следам и находите купца в укрытии вместе с его золотом. Хар считает себя правым ровно до вопроса о царапинах.","f":"Человеческие следы приводят в подготовленную засаду. Начинается битва."},"E390.2":{"s":"Вы платите Хару и Лессу за их разные версии и продолжаете путь. Оба уверяют, что другой ошибается."},"E390.3":{"s":"{{heroName}} обнаруживает, что царапины уводят от дороги вооружённого преследователя, а купец действительно шёл сам. За разгадку получаете золото.","f":"На разветвлении следов {{affectedHeroName}} получает тяжёлое ранение от скрытого нападавшего.","v":{"nf":"Преследователь срывает разведку, но никто из подходящих бойцов не получает тяжёлого ранения. Следы остаются неразобранными."}},"E390.4":{"s":"Вы не становитесь третьим следопытом. Хар и Лесс продолжают спорить, кому принадлежит почти невидимая царапина."},"E391.1":{"s":"Вы делите часы Перра между двумя свадьбами, и в обоих залах наконец начинается правильная музыка. Музыкант платит золотом за спасённый контракт.","f":"Стороны отказываются менять оплаченный порядок танцев и требуют Перра одновременно. Договориться не удаётся."},"E391.2":{"s":"Вы покупаете припасы на кухне между двумя свадебными застольями. Откуда-то доносится мелодия, в которой вальс спорит с маршем."},"E391.3":{"s":"{{heroName}} убеждает семьи обменяться несколькими гостями и расписать выступления. Перр благодарит золотом.","f":"Орки считают перенос боевой песни оскорблением, а люди зовут родню на помощь. Начинается стычка."},"E391.4":{"s":"Вы уходите до совместного танца с топорами. Перр остаётся между залами с одной лютней и двумя расписаниями."},"E392.1":{"s":"Вы освобождаете Ладе проход к П-12, и она проводит необходимое обслуживание. Механик платит золотом за спасённый автомат.","f":"Паломники считают инструменты посягательством на святыню и выходят защищать П-12. Начинается стычка."},"E392.2":{"s":"Вы покупаете припасы у паломников, пока П-12 сообщает об очередной неисправности водяного насоса."},"E392.3":{"s":"{{heroName}} объясняет людям, что помощь ребёнку не отменяет потребности автомата в ремонте. Толпа пропускает Ладу, а она платит золотом.","f":"Паломники отказываются допустить к автомату даже доброжелательного механика. П-12 продолжает требовать ремонт насоса."},"E392.4":{"s":"Вы не решаете, можно ли считать ремонтный автомат святым. Сам П-12 повторяет описание своей прежней работы."},"E393.1":{"s":"Вы открываете мост, который уже неделю выдерживает строителей, и оба мастера получают право на свою единицу длины. Город платит золотом.","f":"Саэль требует записать длину в песнях ветра, а Дурк не готов подписать такой акт. Открытие снова откладывают."},"E393.2":{"s":"Строители продают вам припасы, пока их авторы спорят о числе футов в одной песне ветра."},"E393.3":{"s":"{{heroName}} проверяет крепления и подтверждает, что мост безопасен независимо от названия единиц. Дурк платит золотом.","f":"При проверке опора опасно сдвигается и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Опора срывает испытание, но никто из подходящих бойцов не получает тяжёлого ранения. Мост временно закрывают."}},"E393.4":{"s":"Вы переходите мост без измерений. Саэль и Дурк даже не замечают нового путника посреди своего спора."},"E394.1":{"s":"Вы забираете письмо у скелета и передаёте Гассу через запертую дверь. Демон благодарит золотом, так и не увидев почтальона.","f":"Гасс отказывается брать конверт даже из живых рук, опасаясь прикосновения нежити. Доставка не состоялась."},"E394.2":{"s":"Вы покупаете припасы у хозяина трактира, пока Гасс требует держать скелета подальше от его двери."},"E394.3":{"s":"{{heroName}} объясняет демону, что письмо не превращается в нежить вместе с почтальоном. Гасс открывает дверь и платит золотом.","f":"Гасс принимает уговоры за засаду и зовёт своих вооружённых знакомых. Начинается стычка."},"E394.4":{"s":"Вы уходите, не пытаясь лечить демонические страхи. Скелет спокойно остаётся у двери с нераспечатанным письмом."},"E395.1":{"s":"Вы предлагаете Тарру один берег, а гусям другой, оставив воду общей. Рыбак делится припасами за мирное соседство.","f":"Гуси срывают переговоры громким шипением, и {{affectedHeroName}} получает тяжёлое ранение в суматохе.","v":{"nf":"Переговоры срываются, но никто из подходящих бойцов не получает тяжёлого ранения. Пруд остаётся разделённым."}},"E395.2":{"s":"Вы покупаете у рыбака припасы, пока дракон на своём берегу изучает гусиную дисциплину."},"E395.3":{"s":"{{heroName}} находит Тарру другое укромное место для первых сокровищ. Дракон выдаёт золотую благодарность и уходит от гусей.","f":"Раздражённая стая набрасывается на сопровождающих, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Стая отгоняет сопровождающих, но никто из подходящих бойцов не получает тяжёлого ранения. Тарр остаётся у пруда."}},"E395.4":{"s":"Вы признаёте победу гусей без формального суда. Тарр сердито охраняет три монеты на своём тесном берегу."},"E396.1":{"s":"Вы называете жёлтый цветок садовым растением, которое запрещено трогать без разрешения хозяина. С-9 принимает правило, а Эли благодарит припасами.","f":"Конструкт требует ботанический перечень садовых культур и не принимает словесного исключения. Работа остаётся остановленной."},"E396.2":{"s":"Вы оплачиваете отмену приказа садовнику, и С-9 прекращает уборку сорняков. Эли перестаёт закрывать цветок крыльями."},"E396.3":{"s":"{{heroName}} формулирует критерий, который С-9 может проверить, а Эли признаёт справедливым. Садовник благодарит золотом.","f":"{{heroName}} не находит определения без спорных исключений. С-9 продолжает ждать рабочую команду."},"E396.4":{"s":"Вы оставляете фею и конструкт решать, что такое цветок. Садовник всё ещё не вернулся с обеда."},"E397.1":{"s":"Вы помогаете Гору разжечь костёр и устроить Мере удобный отдых. Ангел благодарит припасами за заботу, даже если нимб пока не светит.","f":"После очередного отвара нимб остаётся тёмным, а Гор признаёт, что способа его починки не нашёл. Дополнительной помощи нет."},"E397.2":{"s":"Вы оставляете орочьей семье припасы, и Гор благодарит золотом. Мера держит горячую чашку уже без возражений."},"E397.3":{"s":"{{heroName}} выясняет вместе с Гором, что нимбу мешает повреждённое крепление, а не простуда. За починку шаман платит золотом.","f":"При проверке нимб разряжается и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Нимб опасно вспыхивает, но никто из подходящих бойцов не получает тяжёлого ранения. Починку приходится отложить."}},"E397.4":{"s":"Вы оставляете ангела у орочьего костра. Гор всё ещё уверен, что тепло однажды поможет даже небесам."},"E398.1":{"s":"Вы досматриваете пьесу, не раскрывая тайну зрителям, и деревенские актёры делятся припасами за поддержку. Ферен наконец вспоминает последнюю реплику.","f":"Ферен забывает весь финал, когда настоящий Король поднимается со скамьи. Представление обрывается."},"E398.2":{"s":"Вы платите труппе за отдельное представление для отряда. Ферен обещает не выдавать настоящего Короля даже случайно."},"E398.3":{"s":"{{heroName}} помогает режиссёру исправить самые нелепые факты, сохранив весёлый финал. Труппа благодарит золотом.","f":"Режиссёр заявляет, что точная история испортит драматический эффект. Переделку откладывают."},"E398.4":{"s":"Вы уезжаете, не раскрыв зрителям, кто сидел среди них. Ферен ещё долго изображает королевский бас увереннее самого оригинала."},"E399.1":{"s":"Вы останавливаете скелетов-лошадей и выводите Яна из последней телеги. Среди багажа находите пригодные припасы.","f":"Мёртвые возчики возвращаются к своему маршруту и поднимают оружие против остановивших караван. Начинается битва."},"E399.2":{"s":"Вы передаёте Яну припасы и показываете, где безопасно сойти при повороте. Мальчик запоминает указания, пока повозки не сбавляют хода."},"E399.3":{"s":"{{heroName}} находит похоронные слова, которыми можно завершить работу возчиков, и караван останавливается. Ян благодарит золотом и припасами.","f":"Мёртвые возчики отвечают на обряд ударом, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Обряд останавливается из-за опасного ответа нежити, но никто из подходящих бойцов не получает тяжёлого ранения. Караван продолжает путь."}},"E399.4":{"s":"Вы уходите от повозок, которые едут без живых возчиков. Ян остаётся в последней телеге, глядя на дорогу не к дому."},"E400.1":{"s":"Вы объявляете дорогу общей и заставляете гоблинов убрать будку. Делегации дают золото за открытый проезд.","f":"Все пять сторон считают решение ущемлением своих заслуг и поднимают вооружённые отряды. Начинается битва."},"E400.2":{"s":"Вы платите гоблинам за проход и оставляете пять делегаций спорить над указателем. Будка немедленно принимает следующего клиента."},"E400.3":{"s":"{{heroName}} предлагает указать на камне имена строителей, хранителей и прежних владельцев отдельно. Делегации выплачивают золото и припасы.","f":"Одной из сторон не хватает места на камне, спор переходит в драку и начинается стычка."},"E400.4":{"s":"Вы тратите припасы на другой тракт, не дожидаясь решения пяти делегаций. Позади гоблины уже продают карты обхода."},"E401.1":{"s":"Вы удерживаете дуэлянтов от взаимного удара и показываете на отстающий колокол. Оба признают ничью, а горожане платят золотом за сохранённый мир.","f":"Дворяне объявляют вмешательство нарушением чести и обнажают клинки против отряда. Начинается стычка."},"E401.2":{"s":"Вы оплачиваете Брану ремонт и забираете припасы для ожидания. На площади по-прежнему спорят, в котором часу началась дуэль."},"E401.3":{"s":"{{heroName}} обнаруживает тайную задержку в ударном механизме и возвращает звон к настоящему часу. Бран благодарит золотом и припасами.","f":"Тяжёлый маятник срывается во время осмотра и ранит {{affectedHeroName}}.","v":{"nf":"Маятник срывается с опоры, но никто из подходящих бойцов не получает тяжёлого ранения. Исправить колокол не успевают."}},"E401.4":{"s":"Вы уезжаете из города, где даже дуэлянты опоздали к собственному поединку. Колокол наконец отбивает вчерашний спор."},"E402.1":{"s":"Вы предъявляете капитану право Короля отменить устаревший приказ, и главные ворота впервые открываются за восемнадцать лет. Горожане возвращают незаконно собранное золото.","f":"Стражники считают попытку отменить приказ надругательством над памятью коменданта и берутся за оружие. Начинается стычка."},"E402.2":{"s":"Вы оплачиваете проход через узкую калитку. Капитан Нелл аккуратно выдаёт квитанцию на проезд одной телеги."},"E402.3":{"s":"{{heroName}} оформляет законную отмену осадного приказа с новой датой и печатью. Нелл благодарит золотом за возможность наконец открыть створки.","f":"{{heroName}} не находит требуемой подписи в старых архивах, и стража взыскивает пошлину за рассмотрение. Казна теряет золото."},"E402.4":{"s":"Вы тратите припасы на внешний обход города. За стенами жители продолжают протискивать повозки в калитку."},"E403.1":{"s":"Вы открываете ворота посёлка, и люди выходят без препятствий. Благодарные жители передают отряду припасы из запасов Севена.","f":"Санитары преграждают дорогу дубинками и вызывают вооружённую охрану карантина. Начинается стычка."},"E403.2":{"s":"Вы покупаете лекарства и провизию у карантинного склада. Севен сердечно поздравляет отряд с отсутствием симптомов."},"E403.3":{"s":"{{heroName}} проверяет истории больных и обнаруживает, что список умерших составлен из живых жителей. Посёлок выплачивает золото за разоблачение.","f":"Санитарная защита срабатывает при вскрытии закрытой палаты, тяжело раня {{affectedHeroName}}.","v":{"nf":"Защита палаты останавливает проверку, но никто из подходящих бойцов не получает тяжёлого ранения. Карантин не снят."}},"E403.4":{"s":"Вы оставляете город за воротами, где здоровье каждого объявлено заслугой доктора. Севен уже поздравляет следующего путника."},"E404.1":{"s":"Лоран соглашается оплатить временный переход, пока рабочие исправляют перевёрнутый настил. Отряду передают золото за помощь в разбирательстве.","f":"Подрядчик упирается в буквальный чертёж и отказывается признавать ошибку. Временной переправы нет."},"E404.2":{"s":"Вы оплачиваете рабочим временный настил и проходите овраг. Часть припасов уходит на укрепление перехода."},"E404.3":{"s":"{{heroName}} находит надёжную нижнюю балку и укрепляет переход для людей. За безопасный проход рабочие оставляют немного припасов.","f":"С нижнего настила срывается крепление, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Настил опасно раскачивается, но никто из подходящих бойцов не получает тяжёлого ранения. Испытание прекращается."}},"E404.4":{"s":"Вы расходуете провизию на длинный обход моста, у которого верх и низ перепутаны. Лоран продолжает ссылаться на чертёж."},"E405.1":{"s":"Вы перехватываете карету перед спуском, и Рем наконец объявляет заседание приостановленным. Судья благодарит золотом за сохранённый процесс.","f":"Карета резко дёргается на повороте, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Повозку бросает на повороте, но никто из подходящих бойцов не получает тяжёлого ранения. Остановить её не удаётся."}},"E405.2":{"s":"Вы ставите нагруженную припасами телегу поперёк пути, и карета останавливается. Рем оплачивает ущерб золотом.","f":"Карета проламывает барьер и уносит часть провизии под колёсами. Судья продолжает заседание на ходу."},"E405.3":{"s":"{{heroName}} догоняет лошадей и берёт поводья до каменного спуска. Рем выплачивает золото за помощь суду.","f":"На обочине лошадь резко отскакивает, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Лошади срывают попытку перехвата, но никто из подходящих бойцов не получает тяжёлого ранения. Карета уходит вниз по дороге."}},"E405.4":{"s":"Вы сходите с дороги, предоставляя суду двигаться своим ходом. Вслед доносится новое признание Костера о преступлении, которого не было."},"E406.1":{"s":"Вы объясняете офицеру, что Крам учит новобранцев выживать после поражения, а не стремиться к нему. Ветеран благодарит припасами за поддержку.","f":"Офицер требует прекратить занятия как позорные, а Крам не готов уступить. Спор продолжается."},"E406.2":{"s":"Крам соглашается учить ваш отряд не только сражаться, но и вовремя складывать оружие. Он вступает в поход.","f":"Ветеран решает, что ученикам на лугу нужнее его опыт, и отказывается от приглашения.","v":{"rs":"Крам согласен служить, но свободного места для нового бойца нет. Он передаёт немного золота в благодарность за уважение."}},"E406.3":{"s":"Новобранцы выстраиваются на учебную стычку и демонстрируют, как быстро умеют признать поражение. Крам довольно командует начать проверку."},"E406.4":{"s":"Вы оставляете Крама обучать полезному военному ремеслу. Молодой офицер пытается понять, можно ли отдать команду «сдаваться» строевым голосом."},"E407.1":{"s":"Дети признаются яблоне, что её плоды были хороши сами по себе. На ветвях вновь появляются яблоки, а садовница выдаёт припасы.","f":"Дети произносят извинение слишком заученно, и ветви демонстративно отворачиваются. Урожая пока нет."},"E407.2":{"s":"Вы покупаете прошлогодние запасы у садовников. Сиэль напоминает всем не сравнивать их вкус с грушами."},"E407.3":{"s":"{{heroName}} проводит обряд благодарности за прежний урожай, и яблоня перестаёт сбрасывать завязи. Отряд заготавливает припасы.","f":"Неверный ритм обряда заставляет ветви сбросить ещё часть собранных припасов. Сиэль просит прекратить попытку."},"E407.4":{"s":"Вы оставляете детей просить прощения у яблони, которая закрыла уши ветвями. Сиэль готовит новую речь."},"E408.1":{"s":"Вы поёте запомненную часть мелодии и находите запас припасов у настоящего перевала. Лиар одобрительно кивает.","f":"Неполная песня вновь приводит к оврагу, и на поиски дороги уходит ещё больше припасов."},"E408.2":{"s":"Вы оплачиваете охотнику дорогу, которую не нужно петь. Он показывает тихую тропу в обход знакомого оврага."},"E408.3":{"s":"{{heroName}} подхватывает конец мелодии по рисунку ткани, и карта впервые показывает целый путь. Отряд находит припасы.","f":"Одна неверная нота ведёт к тупику, и часть провизии расходуется на возвращение."},"E408.4":{"s":"Вы выбираете обычную тропу и тратите припасы на длинный переход. Орин продолжает напевать половину карты."},"E409.1":{"s":"Вы останавливаете оленя и возвращаете письмо Нэри прежде, чем появляется Тален. Лучница благодарит золотом за возможность сказать всё самой.","f":"Олень ускользает к храмовой дороге и не позволяет забрать послание. Нэри придётся встретиться с мужем после доставки."},"E409.2":{"s":"Вы позволяете оленю вручить письмо Талену. Тот читает его при Нэри, и супругам больше некуда прятать разговор."},"E409.3":{"s":"{{heroName}} заходит посланнику наперерез и мягко снимает письмо с зелёной ленты. Нэри благодарит золотом.","f":"Олень резко отбивается рогами, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Посланник отгоняет перехватчиков, но никто из подходящих бойцов не получает тяжёлого ранения. Письмо остаётся у оленя."}},"E409.4":{"s":"Вы уходите, оставив Нэри решать, как говорить с Таленом. Олень уже движется навстречу знакомому голосу."},"E410.1":{"s":"Вы помогаете Элвену очистить источник от тазов, и серебряная вода вновь течёт свободно. Хранитель благодарит припасами.","f":"Стиральщики ссылаются на буквальный текст запрета и не освобождают воду. Очередь корзин растёт."},"E410.2":{"s":"Вы платите за воду и пополняете походные запасы. Элвен наблюдает за тазами с видом человека, проигравшего тысячу лет традиций."},"E410.3":{"s":"{{heroName}} предлагает отдельный ручей для стирки и обряд очищения самого источника. Эльфы соглашаются и делятся припасами.","f":"Вода уходит из старого русла во время работ, и часть припасов портится. Элвен требует вернуть всё как было."},"E410.4":{"s":"Вы оставляете эльфам спорить о тысячелетней традиции и грязных рубахах. Очередь к источнику не становится короче."},"E411.1":{"s":"Висса попадает по колокольчику за ширмой и выигрывает турнир. Вы забираете золото по удачной ставке.","f":"Стрела Виссы уходит мимо звона, а ваша ставка остаётся у распорядителя. Торговец в пробитой шляпе не радуется."},"E411.2":{"s":"Вы переносите зрителей за безопасную черту, а судья вынужден признать ветер не единственной опасностью. За помощь отряду дают припасы.","f":"Айрен считает перенос публики нарушением древних правил, и стрелки продолжают готовиться у той же ширмы."},"E411.3":{"s":"{{heroName}} находит в правилах право судьи расширять защитный круг и заставляет выполнить его. Айрен платит золотом за спасённый турнир.","f":"{{heroName}} не успевает убедить судей до следующего выстрела, а организаторы взыскивают плату за проверку. Казна теряет золото."},"E411.4":{"s":"Вы покидаете турнир до новой случайной мишени. Торговец бережно складывает свою дырявую шляпу."},"E412.1":{"s":"Вы находите в следах подсказку: последняя фигура позволяла танцорам разойтись и встретиться вновь. Аэрин благодарит припасами за восстановление.","f":"Старые отпечатки расходятся в разные стороны, не оставив ни одного надёжного шага. Ритуал продолжается без конца."},"E412.2":{"s":"Аэрин соглашается честно назвать новое движение новым и разрешает танец закончить. Эльфы благодарят золотом за сохранённое будущее.","f":"Старейшины не желают вводить новшество в столетний обряд. Сорок восьмой шаг остаётся пустым."},"E412.3":{"s":"{{heroName}} находит в старых песнях смысл последней фигуры и восстанавливает ритуал. Аэрин вручает золото.","f":"При попытке повторить утраченную фигуру срабатывает охранный знак, тяжело раня {{affectedHeroName}}.","v":{"nf":"Охранный знак прерывает танец, но никто из подходящих бойцов не получает тяжёлого ранения. Последний шаг ещё не восстановлен."}},"E412.4":{"s":"Вы оставляете эльфам право самим придумать или восстановить завершение танца. Аэрин всё ещё изучает старые следы."},"E413.1":{"s":"Оба клана пробуют две похлёбки и признают, что ни одна не хуже другой. Грум выдаёт отряду припасы за оконченный спор.","f":"Шаман Тарга объявляет дегустацию нарушением обряда, и вооружённые сторонники сходятся у котла. Начинается стычка."},"E413.2":{"s":"Вы покупаете у Грума несколько котелков священной похлёбки и пополняете запасы. Тарга настойчиво требует не называть её ужином."},"E413.3":{"s":"{{heroName}} соединяет два рецепта так, что каждый клан узнаёт вкус предков. Отряду достаются припасы от довольных поваров.","f":"Старейшины замечают обман и обвиняют смешавших рецепты в святотатстве. Начинается стычка."},"E413.4":{"s":"Вы уходите, пока орки делят авторство похлёбки. Тарга уже просит четвёртую миску исключительно ради проверки."},"E414.1":{"s":"Вы напоминаете совету, что Могра растила Яна пять лет, а камень не знает семьи. Клан признаёт мальчика своим и выдаёт припасы.","f":"Бург настаивает на старом испытании, не позволяя заменить его семейным признанием. Решение откладывается."},"E414.2":{"s":"Ян проходит проверку на знание языка и истории клана, а старейшина признаёт это настоящим испытанием. Могра благодарит золотом.","f":"Часть воинов считает новое испытание издёвкой и выходит защищать прежний порядок силой. Начинается стычка."},"E414.3":{"s":"{{heroName}} придумывает долгий путь с тяжёлым, но посильным снаряжением, и Ян выдерживает его. Бург благодарит золотом за честную замену.","f":"На испытании срывается опора и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Испытание приходится прервать из-за опасного срыва, но никто из подходящих бойцов не получает тяжёлого ранения. Ян остаётся ждать решения."}},"E414.4":{"s":"Вы оставляете Могру и Яна перед старейшиной с ритуальным камнем. Мальчик крепче сжимает рукоять чужого большого топора."},"E415.1":{"s":"Вы предлагаете считать только раны, полученные в бою и подтверждённые свидетелями. Уграт выдаёт золото за понятную ведомость.","f":"Крош находит новых свидетелей своей порезанной руки и требует считать её боевой. Очередь опять спорит."},"E415.2":{"s":"Крош убеждает казначея считать порез армейской травмой, и ваша ставка приносит золото.","f":"Уграт признаёт порез бытовым, а внесённая ставка остаётся у букмекеров."},"E415.3":{"s":"{{heroName}} разбирает шрамы и подтверждения отдельно, закрыв спор о длинной ране и двух коротких. Казначей платит золотом.","f":"{{heroName}} не находит нужных записей, а за разбирательство казна теряет золото. Уграт возвращается к подсчётам."},"E415.4":{"s":"Вы не берётесь определять цену чужих шрамов. Крош уже готов продемонстрировать, как получил порез у казны."},"E416.1":{"s":"Вы задерживаете разведчика без участия Шмыга, и Гарк выдаёт золото за помощь. Кабан продолжает изучать цветы.","f":"Разведчик зовёт свою охрану, и перехват превращается в стычку."},"E416.2":{"s":"Вы покупаете у Гарка походный корм, который Шмыг больше не хочет есть перед боем. Орк вздыхает над оставшимся мешком."},"E416.3":{"s":"{{heroName}} спокойно уводит Шмыга с дороги, не требуя атаки. Гарк благодарит золотом за возвращённого кабана.","f":"Кабан пугается попытки сдвинуть его и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Шмыг отталкивает провожатых, но никто из подходящих бойцов не получает тяжёлого ранения. Кабан остаётся у цветов."}},"E416.4":{"s":"Вы уважаете решение Шмыга не воевать сегодня. Гарк ещё раз просит кабана хотя бы посмотреть грозно."},"E417.1":{"s":"Посол принимает мысль о мире сразу с тремя кланами, и Раг наконец прекращает ждать новой войны. Отряду платят золотом за спасённую дипломатию.","f":"Хара считает новое толкование провокацией и выводит сторонников на стычку."},"E417.2":{"s":"Вы оплачиваете татуировщику исправление, и Раг получает договор с правильным именем на спине. Мастер выдаёт припасы за помощь."},"E417.3":{"s":"{{heroName}} находит в старом обряде право вписывать имя третьего клана как знак будущего перемирия. Хара благодарит золотом.","f":"{{heroName}} не может найти признанное толкование для ошибочной надписи. Хара продолжает требовать исправления."},"E417.4":{"s":"Вы покидаете Рага до прибытия третьего клана. Вождь наконец просит зеркало, чтобы увидеть собственную спину."},"E418.1":{"s":"Вы расходуете припасы на обход ближайшей реки. Куга продолжает вспоминать, о какой переправе спрашивал барабан."},"E418.2":{"s":"Вы переходите ближайшую реку без происшествий и находите на дальнем берегу уцелевшие припасы.","f":"На переправе {{affectedHeroName}} получает тяжёлое ранение из-за внезапного подъёма воды.","v":{"nf":"Вода поднимается опасно, но никто из подходящих бойцов не получает тяжёлого ранения. Переход приходится прекратить."}},"E418.3":{"s":"{{heroName}} восстанавливает вчерашний порядок ударов и понимает, что барабан предупреждал о дальней реке. Куга выдаёт припасы за найденный ответ.","f":"Для повторения обряда расходуются припасы, но барабан молчит до следующего дня. Проверка не помогает."},"E418.4":{"s":"Вы уходите, не проверяя пророчество с суточной задержкой. Куга уже готовит новый вопрос, который забудет завтра."},"E419.1":{"s":"Вы отделяете голоса от молчания, и жители некрополя выбирают старосту настоящим подсчётом. Комиссия благодарит золотом.","f":"Часть избирателей не может покинуть могилы, а кандидаты спорят, как учитывать отсутствие. Итоги не утверждены."},"E419.2":{"s":"Вы поддерживаете комиссию золотом, и она выдаёт припасы на дорогу в благодарность. Из земли наконец выносят дополнительные урны."},"E419.3":{"s":"{{heroName}} находит в уставе правило: не проголосовавший не считается сторонником действующей власти. Некрополь платит золотом за ясный итог.","f":"{{heroName}} не находит статьи о голосовании тех, кто физически не встаёт, и спор требует платного разбирательства. Казна теряет золото."},"E419.4":{"s":"Вы оставляете некрополь решать, чьё молчание является голосом. Гесс уже заказывает новый фонарь для избирательного участка."},"E420.1":{"s":"Вы показываете Бему место старого дома на карте Коры, и призрак прекращает мучить нового хозяина. Благодарная вдова выдаёт припасы.","f":"Бем отказывается верить, что настоящий дом снесли, и вновь требует признания у нынешнего жильца. Проблема не решена."},"E420.2":{"s":"Вы покупаете у Коры старые запасы из погреба, пока Бем изучает карту городских участков."},"E420.3":{"s":"{{heroName}} проводит Бема к бывшему дому и завершает разговор с прошлым без новых обвинений. Вдова благодарит золотом.","f":"На старом участке проявляется враждебная печать и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Старая печать мешает обряду, но никто из подходящих бойцов не получает тяжёлого ранения. Бем продолжает искать виновного."}},"E420.4":{"s":"Вы уходите, оставляя Бема спорить с городской нумерацией. Нынешний хозяин дома наконец запирает дверь на ночь."},"E421.1":{"s":"В глубине погреба обнаруживается потайная дверца в старый тоннель и оставленная похитителями золотая плата. Лоран впервые спрашивает, кто знал о проходе.","f":"Из тоннеля выходят вооружённые слуги неизвестного покупателя. Начинается стычка."},"E421.2":{"s":"Вы продаёте Лорану припасы, а вампир платит золотом, не объясняя, для чего они нужны пустому погребу."},"E421.3":{"s":"{{heroName}} замечает, что записи управляющего внесены не рукой, а повторяющим её механизмом. Лоран благодарит золотом за разгадку.","f":"{{heroName}} не может доказать подделку записей, и управляющий взыскивает плату за проверку. Казна теряет золото."},"E421.4":{"s":"Вы оставляете Лорана среди пустых полок и не спрашиваете, что именно было в бутылках. Скелет вновь пересчитывает ноль."},"E422.1":{"s":"Вы открываете сундук, который Аркат трижды проверял снаружи, и находите его бесценную вещь рядом с золотом. Лич облегчённо закрывает крышку.","f":"Сундук отвечает защитной вспышкой, и {{affectedHeroName}} получает тяжёлое ранение.","v":{"nf":"Защита сундука срабатывает, но никто из подходящих бойцов не получает тяжёлого ранения. Аркат продолжает поиски."}},"E422.2":{"s":"Вы оставляете Аркату припасы для продолжения поисков, и лич платит золотом. Скелеты уже переставляют мебель четвёртый раз."},"E422.3":{"s":"Один из скелетов с облегчением соглашается служить Королю вместо поисков потерянной вещи. Он вступает в отряд.","f":"Скелет боится, что Аркат заметит его отсутствие раньше пропажи, и остаётся в лаборатории.","v":{"rs":"Скелет согласен покинуть лабораторию, но места в отряде нет. Он благодарит золотом и возвращается к поискам."}},"E422.4":{"s":"Вы не спрашиваете, без чего личу столь неудобно существовать. За спиной скелет снова указывает на крышку сундука."},"E423.1":{"s":"Вы выводите живого Фела из-под погребального полотна, и он делится найденными припасами. Мор грозит подать отчёт о недостаче.","f":"Мор зовёт вооружённых могильщиков, считая спасение нарушением оплаченной перевозки. Начинается стычка."},"E423.2":{"s":"Вы оплачиваете исправление ведомости, Фел выбирается из повозки и отдаёт вам дорожные припасы в благодарность."},"E423.3":{"s":"{{heroName}} снимает полотно, пока Мор пересчитывает тела, и Фел соскальзывает на дорогу. Спасённый передаёт припасы.","f":"Возчик замечает исчезновение пассажира и зовёт вооружённую погребальную команду. Начинается стычка."},"E423.4":{"s":"Вы не спорите с кладбищенской службой, где живого записали в покойники. Фел продолжает махать из-под полотна."},"E424.1":{"s":"Вы находите в склепе старые детские вещи и закрытый золотой ларец. Песня стихает на последней строке.","f":"Слова колыбельной пробуждают вооружённых обитателей склепа. Начинается битва."},"E424.2":{"s":"Вы оставляете могильщикам припасы для укрепления входа, а Вена благодарит золотом. Из-под земли по-прежнему звучит просьба."},"E424.3":{"s":"{{heroName}} проводит обряд памяти у старого склепа, и голоса успокаиваются. Вена выдаёт золото и припасы за возвращённый покой.","f":"Погребальная печать отвечает ударом и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Печать срывает обряд, но никто из подходящих бойцов не получает тяжёлого ранения. Колыбельная продолжается."}},"E424.4":{"s":"Вы уходите с кладбища до ночи. Последняя строка колыбельной доносится даже до дороги."},"E425.1":{"s":"Паук наконец подходит к Дарену, и тот получает свиток при свидетелях. Вейра платит золотом за окончание долгой доставки.","f":"Дарен зовёт вооружённых друзей против попытки заставить его принять письмо. Начинается стычка."},"E425.2":{"s":"Вейра и Дарен соглашаются говорить друг с другом без восьминогого посредника. За прекращённый спор вам передают золото.","f":"Оба настаивают на соблюдении свадебного обряда, а паук продолжает сидеть между ними. Разговор не получается."},"E425.3":{"s":"{{heroName}} успокаивает паука и доводит его до Дарена со свитком на лапе. Вейра благодарит золотом.","f":"Паук резко разворачивается на поводке и тяжело ранит {{affectedHeroName}}.","v":{"nf":"Паук отказывается идти и отталкивает сопровождающих, но никто из подходящих бойцов не получает тяжёлого ранения. Письмо не вручено."}},"E425.4":{"s":"Вы оставляете супругов спорить о разводе, для которого требуется паук. Тот удобно устраивается возле Дарена."},"E426.1":{"s":"Вы убеждаете клиентов оплачивать материалы, дорогу и непредвиденные обстоятельства по договору. Гильдия благодарит золотом за прекращённую забастовку.","f":"Один из заказчиков объявляет переговорщиков сообщниками бастующих и хватается за оружие. Начинается стычка."},"E426.2":{"s":"Вы оплачиваете проход по территории гильдии. Ассасины в пустых ножнах вежливо пропускают отряд."},"E426.3":{"s":"{{heroName}} разделяет фиксированную плату и расходы на выполнение заказов; обе стороны принимают новую таблицу. Гильдия платит золотом.","f":"{{heroName}} не убеждает клиентов признать доплаты, а гильдия взыскивает сбор за посредничество. Казна теряет золото."},"E426.4":{"s":"Вы тратите припасы на обход квартала бастующих убийц. Сарис продолжает уверять прохожих, что сегодня они в безопасности."},"E427.1":{"s":"Вы останавливаете недовольных покупателей, а Иллис убирает зеркало с улицы. Торговка благодарит золотом за спасённую лавку.","f":"Клиенты решают разбить зеркало вместе с охраной, и у прилавка начинается стычка."},"E427.2":{"s":"Вы покупаете у Иллис припасы вместо обсидианового зеркала. Оно успевает сообщить торговке, что ценник действительно завышен."},"E427.3":{"s":"Иллис возвращает покупателям деньги и платит отряду золото за урегулирование претензий.","f":"Иллис объявляет, что правду невозможно вернуть как неисправный товар. Покупатели остаются без денег."},"E427.4":{"s":"Вы уходите, не спрашивая зеркало, что оно думает о Короле. Оно вдруг громко замечает, что молчание тоже многое говорит."},"E428.1":{"s":"Лиасса сама выбирает, где и с кем хочет жить, и обе матроны вынуждены услышать её ответ. Девушка благодарит припасами за право слова.","f":"Лиасса не готова решать при двух спорящих матерях и просит оставить её одну. Спор пока продолжается."},"E428.2":{"s":"Вы не вмешиваетесь в родовой спор двух подлинных договоров. Лиасса смотрит вслед, не произнося ни слова."},"E428.3":{"s":"{{heroName}} находит отдельный договор об обмене детьми, подписанный обеими матронами в ту самую ночь. Семьи платят золотом за восстановленную правду.","f":"{{heroName}} сталкивается с двумя законными, но противоречащими расписками; стороны требуют оплатить разбирательство. Казна теряет золото."},"E428.4":{"s":"Лиасса соглашается уйти с Королём, чтобы впервые принимать решения вне двух домов. Она вступает в отряд.","f":"Матроны зовут охрану и запрещают Лиассе уходить с незнакомцами. Начинается стычка.","v":{"rs":"Лиасса готова отправиться в поход, но места в отряде нет. В благодарность за предложенный выход она передаёт золото."}},"E429.1":{"s":"Вы обнаруживаете наёмного убийцу до удара и заставляете его отказаться от контракта. Иара платит золотом за сохранённую жизнь.","f":"Исполнитель раскрывает засаду только после наступления темноты и приводит вооружённых сообщников. Начинается битва."},"E429.2":{"s":"Вы оплачиваете отмену, и Кес получает письменное подтверждение от гильдии. Благодарный ученик возвращает отряду золото.","f":"Исполнитель уже приступил к заданию и отказывается отменять его даже за плату. Переговоры не спасают наставника."},"E429.3":{"s":"{{heroName}} замечает среди прохожих человека, который никогда не отводит глаз от Иары. За раскрытого наблюдателя ученик платит золотом.","f":"Наблюдатель ранит {{affectedHeroName}}, прежде чем его удаётся вывести из толпы.","v":{"nf":"Наблюдатель скрывается после опасной стычки, но никто из подходящих бойцов не получает тяжёлого ранения. Исполнитель остаётся неизвестным."}},"E429.4":{"s":"Вы отказываетесь участвовать в выпускном экзамене на убийство собственного учителя. Кес снова умоляет Иару спрятаться."},"E430.1":{"s":"Вы повторяете жест опытного покупателя и незаметно выходите из торгов с золотой прибылью. Сел вежливо склоняет голову.","f":"Сел принимает движение за повышение ставки и взыскивает штраф золотом за нарушение правил. Отряду приходится заплатить."},"E430.2":{"s":"Вы уплачиваете штраф за ошибочную ставку и выходите из безмолвного зала. Аукционистка даже не повышает голоса."},"E430.3":{"s":"{{heroName}} быстро осваивает язык жестов и перепродаёт ставку другому гостю. Казна получает золото.","f":"{{heroName}} путает знак отказа с дополнительной ставкой, и отряд теряет золото."},"E430.4":{"s":"Король громко произносит «нет» и немедленно покидает зал согласно правилу о нарушителях. Сел указывает на выход без единого слова."}});
export { OUTCOMES_E361_E430 };
